window.T24_DASHBOARD_UNITS = [{"unit":1,"theme":"armed – ditch","cards":[{"w":"armed","p":"adj.","d":"equipped with weapons; supplied with necessary information or tools","c":"武裝的；攜帶武器的；備妥裝備的","s":"The security guards patrolling the international terminal were fully armed to ensure the safety of travelers.","t":"巡邏國際航廈的保全人員全副武裝，以確保旅客的安全。"},{"w":"bacon","p":"n.","d":"cured meat from the sides or belly of a pig, typically fried in slices","c":"培根；燻豬肉","s":"Every weekend, the traditional cafe serves a delicious breakfast featuring crispy fried bacon and fluffy scrambled eggs.","t":"每逢週末，這間傳統咖啡館都會供應美味的早餐，主打香脆的煎培根與蓬鬆的炒蛋。"},{"w":"badly","p":"adv.","d":"in an unsatisfactory, defective, or severe way; very much","c":"拙劣地；嚴重地；極其","s":"The historic municipal library was badly damaged by the raging storm and required extensive restoration.","t":"這座歷史悠久的市立圖書館遭受狂風暴雨的嚴重損壞，需要進行大規模的修復。"},{"w":"breeze","p":"n./v.","d":"a gentle, pleasant wind; something very easy to accomplish","c":"微風；輕而易舉的事 (n.)；輕快地走 (v.)","s":"We sat on the oceanfront veranda and thoroughly enjoyed the refreshing cool breeze blowing across the bay.","t":"我們坐在面海的陽台上，徹底享受著吹拂過海灣的清新涼爽微風。"},{"w":"clothe","p":"v.","d":"to provide with clothes; to put clothes on someone or dress","c":"為…穿衣；覆蓋；籠罩","s":"The caring mother gently clothed her shivering toddler in a thick woolen sweater before going outdoors into the cold.","t":"這位關懷備至的母親在走到戶外嚴寒之前，溫柔地為顫抖的幼童穿上一件厚毛衣。"},{"w":"crew","p":"n.","d":"a group of people who work on and operate a ship, aircraft, or project","c":"全體船員/機組人員；工作團隊","s":"The attentive cabin crew demonstrated essential safety protocols and calmly served hot beverages to all passengers.","t":"細心的機組工作人員示範了關鍵的安全守則，並平靜地為所有乘客送上熱飲。"},{"w":"dealer","p":"n.","d":"a person or firm that buys and sells goods; a card distributor in games","c":"經銷商；商人；發牌員","s":"Before purchasing the imported sedan, my father negotiated aggressively with the experienced car dealer to secure a reasonable discount.","t":"在購買進口轎車之前，我父親與經驗豐富的汽車經銷商積極協商，以爭取合理的折扣。"},{"w":"ditch","p":"n./v.","d":"a narrow channel dug at the side of a road; to discard or abandon","c":"水溝；溝渠 (n.)；拋棄；丟下 (v.)","s":"Due to the slippery frozen road, the postal delivery truck lost control and slid directly into a roadside ditch.","t":"由於濕滑結冰的道路，郵務貨車失去控制，直接滑進了路邊的水溝。"}]},{"unit":2,"theme":"dizzy – interrupt","cards":[{"w":"dizzy","p":"adj.","d":"having a sensation of spinning and losing one's balance; causing vertigo","c":"頭暈目眩的；令人頭暈的","s":"After spinning quickly on the amusement park ride, the young boy felt so dizzy that he had to sit on a bench.","t":"在遊樂園的遊樂設施上飛速旋轉後，小男孩感到非常頭暈，不得不坐在長凳上。"},{"w":"edit","p":"v.","d":"to prepare written or video material for publication by correcting or modifying","c":"編輯；編校；剪輯","s":"The creative director spent entire nights learning how to edit documentary footage using sophisticated computer software.","t":"這位創意總監整夜學習如何使用先進的電腦軟體來剪輯紀錄片毛片。"},{"w":"fountain","p":"n.","d":"an ornamental structure in a pool jetting water; an abundant source","c":"噴水池；飲水器；泉源","s":"Enchanted visitors gathered around the ornate marble fountain in the central square to toss shiny coins and make wishes.","t":"著迷的遊客聚集在中央廣場華麗的大理石噴泉周圍，丟擲閃亮的硬幣並許下願望。"},{"w":"headline","p":"n./v.","d":"a heading at the top of an article or page in a newspaper; to star in","c":"頭條新聞；大字標題 (n.)；為…加標題；主演 (v.)","s":"The historic peace treaty between the two conflicting nations made the headlines across every major international publication.","t":"這兩個衝突國家之間簽署的歷史性和平條約，登上了各大主要國際刊物的頭條新聞。"},{"w":"heel","p":"n./v.","d":"the back part of the human foot below the ankle; the rear part of a shoe","c":"腳後跟；鞋跟 (n.)；緊跟在後 (v.)","s":"Although the brilliant mathematician solved complex formulas effortlessly, his lack of organizational discipline proved to be his Achilles' heel.","t":"雖然這位才華橫溢的數學家能毫不費力地解出複雜的公式，但他缺乏條理的紀律卻成了他的致命要害。"},{"w":"hesitate","p":"v.","d":"to pause before saying or doing something through doubt or indecision","c":"猶豫；躊躇；遲疑","s":"If you encounter any technical difficulties during online examination registration, please do not hesitate to contact our customer support team. The brave lifeguard jumped into the stormy ocean current without a moment's hesitation to rescue the struggling swimmer.","t":"若您在線上考試報名過程中遇到任何技術困難，請毫不猶豫地聯絡我們的客戶支援團隊。 這位勇敢的救生員毫不猶豫地跳入狂暴的洋流中，奮力營救正在掙扎的泳客。"},{"w":"homesick","p":"adj.","d":"experiencing a longing for one's home during an absence from it","c":"思鄉的；想家的","s":"During her first semester studying abroad in London, Amanda felt terribly homesick whenever she thought of her family and hometown cooking.","t":"在倫敦留學的第一個學期裡，每當想念家人與家鄉菜餚時，Amanda 都會感到極度想家。"},{"w":"interrupt","p":"v.","d":"to stop the continuous progress of an activity or speaker by interjecting","c":"打斷；打擾；中斷","s":"It is considered impolite in formal diplomatic negotiations to interrupt a speaker before they have completely finished expressing their perspective.","t":"在正式的外交談判中，在發言者完全陳述完觀點之前予以打斷，被視為極其失禮之舉。"}]},{"unit":3,"theme":"junior – racial","cards":[{"w":"junior","p":"adj./n.","d":"having a lower status or age than another; a third-year student","c":"資淺的；年少的 (adj.)；後進；大三生 (n.)","s":"Although Mark had exceptional technical skills, he was junior to several veteran engineers who had served the company for decades.","t":"雖然 Mark 擁有卓越的專業技術，但相較於為該公司服務了數十年的幾位資深工程師，他的資歷仍屬較淺。"},{"w":"laughter","p":"n.","d":"the action or sound of laughing","c":"笑；笑聲","s":"The hilarious stand-up comedian delivered such witty jokes that the entire theater audience spontaneously burst into uncontrollable laughter.","t":"這位幽默的單口喜劇演員講述了非常詼諧的笑話，以至於全場戲院觀眾不由自主地爆發出難以抑制的笑聲。"},{"w":"laundry","p":"n.","d":"clothes and linens that need to be washed or that have been newly washed","c":"送洗之衣物；洗衣店","s":"Every Sunday afternoon, David sorts through his clothes and spends hours doing the weekly laundry at the community laundromat.","t":"每逢週日下午，David 都會將衣服分類，並在社區自助洗衣店花上數小時清洗每週的待洗衣物。"},{"w":"penny","p":"n.","d":"a one-cent coin or unit of currency in the US or UK","c":"一分錢；便士","s":"Restoring the rare vintage sports car required rare original replacement parts that ultimately cost the proud owner a pretty penny.","t":"修復這輛罕見的古董跑車需要稀有的原廠零件，最終讓這位自豪的車主花費了一大筆錢。"},{"w":"pigeon","p":"n.","d":"a stout seed-eating or fruit-eating bird with a small head and cooing call","c":"鴿子","s":"On sunny weekends, retirees enjoy sitting quietly in the historic town square to feed the pigeons scattered around the fountain.","t":"在陽光明媚的週末，退休長者們喜愛靜靜坐在歷史悠久的城鎮廣場上，餵食散佈在噴泉周圍的鴿子。"},{"w":"pity","p":"n./v.","d":"the feeling of sorrow and compassion caused by the suffering of others","c":"同情；憐憫；憾事 (n.)；同情；憐惜 (v.)","s":"Seeing the shivering stray dog caught in the pouring rain, the kindhearted shopkeeper took pity on the creature and offered it food.","t":"看到在傾盆大雨中瑟瑟發抖的流浪狗，善良的店主同情這隻小動物，並給了牠一些食物。"},{"w":"process","p":"n./v.","d":"a series of actions or steps taken to achieve an end; to treat or handle","c":"過程；步驟 (n.)；處理；加工 (v.)","s":"The municipal research team is currently in the process of evaluating local groundwater quality following the chemical plant inspection.","t":"在化學工廠檢查之後，市府研究團隊目前正在評估當地地下水水質的過程當中。"},{"w":"racial","p":"adj.","d":"relating to the major human ethnic divisions or ancestry","c":"種族的；人種的","s":"Civil rights advocates marched peacefully through the capital streets to demand strict legal prohibitions against systemic racial discrimination in housing.","t":"民權倡議者和平遊行穿過首都街頭，要求針對住房領域系統性的種族歧視採取嚴格的法律禁令。"}]},{"unit":4,"theme":"sake – underlying","cards":[{"w":"sake","p":"n.","d":"for the purpose of; in the interest of; out of consideration for","c":"緣故；好處；利益","s":"For the sake of their children's future education, the devoted parents decided to relocate closer to the university district.","t":"為了子女未來的教育著想，這對全心奉獻的父母決定搬遷至離大學城更近的地區。"},{"w":"someday","p":"adv.","d":"at some indefinite or unspecified time in the future","c":"有朝一日；總有一天","s":"The talented young pianist dreamed that someday she would perform a solo concerto at Carnegie Hall in New York.","t":"這位才華洋溢的年輕鋼琴家夢想著有朝一日能在紐約卡內基音樂廳舉辦個人獨奏協奏曲演出。"},{"w":"squeeze","p":"v./n.","d":"to firmly press something soft; to force into or through a tight space","c":"壓榨；擠出；塞進 (v.)；緊握；壓榨 (n.)","s":"Before grilling the fresh salmon fillet, the chef squeezed a ripe lemon gently to enhance the delicate flavor.","t":"在燒烤新鮮鮭魚排之前，主廚輕輕擠壓一顆成熟的檸檬以提升細緻的風味。"},{"w":"tight","p":"adj./adv.","d":"fixed, fastened, or fitting very closely; with little money or time to spare","c":"緊密的；緊湊的 (adj.)；緊緊地 (adv.)","s":"Due to unexpected shipping delays from overseas, the construction project had to operate under an extremely tight schedule.","t":"由於來自海外的貨運意外延誤，該營建工程必須在極其緊湊的時程表下趕工進行。"},{"w":"tighten","p":"v.","d":"to make or become tight or tighter; to impose stricter controls on","c":"使變緊；勒緊；加強 (管制)","s":"Facing a severe economic downturn, household members agreed to tighten their belts and cut down on non-essential entertainment expenses.","t":"面對嚴峻的經濟衰退，全家成員一致同意勒緊褲帶節約開支，減少非必要的娛樂花費。"},{"w":"trace","p":"v./n.","d":"to find or discover by investigation; a mark, object, or sign left by something","c":"追溯；追蹤 (v.)；蹤跡；微量 (n.)","s":"Archaeologists determined that the ancient pottery decorative patterns could be traced back to prehistoric tribal rituals.","t":"考古學家判定，這批古代陶器的裝飾圖案可以追溯至史前部落的祭祀儀式。"},{"w":"underlying","p":"adj.","d":"lying beneath; fundamental, basic, or serving as the foundation of","c":"潛在的；根本的；位於下方的","s":"Investigative journalists revealed that financial greed and lack of regulation were the true underlying causes of the bank failure.","t":"調查記者揭露，金融貪婪與缺乏監管才是該銀行破產倒閉真正的根本原因。"}]}];
